import numpy as np
# Baseline subtraction using points at 1100 and 1800 cm-1 (+/- 10)
def get_baseline_val(shifts, intensities, target_center):
    mask = (shifts >= target_center - 10) & (shifts <= target_center + 10)
    if not np.any(mask):
        return np.interp(target_center, shifts, intensities)
    return np.mean(intensities[mask])

b1 = get_baseline_val(x, y1, 1100)
b2 = get_baseline_val(x, y1, 1800)

# Create linear baseline array
baseline = np.linspace(b1, b2, len(x))
y1_corrected = y1 - baseline

# Normalize to G-band max (1550-1620)
g_mask = (x >= 1550) & (x <= 1620)
if np.any(g_mask):
    g_max = np.max(y1_corrected[g_mask])
    if g_max != 0:
        y1_final = y1_corrected / g_max
    else:
        y1_final = y1_corrected
else:
    y1_final = y1_corrected

y1 = y1_final
